function background(s){let palettes=[['#1a1723','#332737'],['#704e4b','#bd7865'],['#11201c','#263b2e'],['#171329','#302344']][mode],g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,palettes[0]);g.addColorStop(1,palettes[1]);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#ffffff09';ctx.lineWidth=1;for(let x=0;x<W;x+=48){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<H;y+=48){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}if(mode===0){ctx.fillStyle='#0e101ccc';[[10,15,250,105],[318,16,250,90],[660,18,260,105],[25,420,230,104],[340,438,230,86],[700,420,240,100]].forEach(b=>{ctx.fillRect(...b);ctx.strokeStyle='#72606c';ctx.strokeRect(...b);for(let x=b[0]+14;x<b[0]+b[2]-8;x+=38){ctx.fillStyle='#e4bc8133';ctx.fillRect(x,b[1]+18,15,8)}ctx.fillStyle='#0e101ccc'});s.lamps.forEach(l=>{if(l.on)glow(l.x,l.y,90,'#f9d38755');circle(l.x,l.y,4,l.on?'#ffe7a4':'#57505b')})}if(mode===1){ctx.fillStyle='#e9a67630';ctx.fillRect(0,0,W,H);getShadows(s.time).forEach(sh=>{glow(sh.x,sh.y,sh.r+35,'#100d23bb');circle(sh.x,sh.y,sh.r,'#171629dd')});s.lanterns.forEach(l=>{let x=l.x+Math.cos(s.time*.65+l.phase)*155,y=l.y+Math.sin(s.time*.65+l.phase)*155;ctx.strokeStyle='#ffe9bc55';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(l.x,l.y);ctx.lineTo(x,y);ctx.stroke();glow(x,y,60,'#ffd08b99');circle(l.x,l.y,5,'#ffdfad')})}if(mode===2){for(let i=0;i<35;i++){let x=(i*173)%W,y=(i*97)%H;circle(x,y,2,'#a7c4a64a')}}if(mode===3){ctx.strokeStyle='#c8a2ff33';for(let y=110;y<430;y+=64){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}s.song.slice(-18).forEach((n,i)=>{circle(35+i*50,390-n*40,6,'#e9d2ff99')});for(let i=0;i<50;i++){let x=(i*173)%W,y=(i*97)%H;circle(x,y,1+Math.sin(s.time+i)*.6,'#e0c7ff99')}}}
function character(x,y,color,kind,angle=0){ctx.save();ctx.translate(x,y);if(kind==='vamp'){ctx.rotate(angle);ctx.fillStyle='#120d1c';ctx.beginPath();ctx.moveTo(-9,-7);ctx.lineTo(-22,-20);ctx.lineTo(-14,0);ctx.lineTo(-22,20);ctx.lineTo(-9,7);ctx.fill();circle(0,0,10,color);circle(5,-3,2,'#322b32');circle(5,3,2,'#322b32')}else if(kind==='hunter'){ctx.fillStyle='#d76274';ctx.fillRect(-9,-9,18,18);ctx.fillStyle='#ffe0bd';ctx.fillRect(-5,-7,10,6);ctx.fillStyle='#302734';ctx.fillRect(-12,-14,24,5)}else{circle(0,0,8,color);ctx.fillStyle='#2c2533';ctx.fillRect(-6,-10,12,5)}ctx.restore()}
function drawCourt(s){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#211b2b');g.addColorStop(1,'#564337');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);glow(480,175,260,'#d3a37b33');ctx.fillStyle='#15121a';ctx.fillRect(100,180,760,240);for(let i=0;i<7;i++){let x=150+i*100;ctx.fillStyle='#382a31';ctx.beginPath();ctx.arc(x,240,34,Math.PI,0);ctx.lineTo(x+34,370);ctx.lineTo(x-34,370);ctx.closePath();ctx.fill();ctx.fillStyle=i<s.night?'#e3bd83':'#594653';ctx.fillRect(x-15,250,30,90)}ctx.fillStyle='#f0dfca';ctx.font='36px Georgia';ctx.fillText('THE MIDNIGHT COURT',76,80);ctx.fillStyle='#c8b4ad';ctx.font='18px sans-serif';ctx.fillText(s.sceneTitle||'THE FIRST NIGHT',76,115);ctx.font='16px sans-serif';ctx.fillText(s.sceneText||'',76,145);ctx.fillStyle='#d9f878';ctx.font='bold 16px sans-serif';ctx.fillText('NIGHT '+Math.min(s.night,7)+' / 7',76,475);ctx.fillStyle='#d8c6bb';ctx.font='15px sans-serif';ctx.fillText('The city remembers every choice.',76,505)}
function draw(){if(!state){drawIntro();return}let s=state;if(mode===4){drawCourt(s);return}ctx.save();if(s.shake)ctx.translate(rand(-s.shake,s.shake),rand(-s.shake,s.shake));background(s);s.items.forEach(a=>{let col=a.kind==='stone'?'#98edff':a.kind==='note'?'#e1bdff':'#f6d39b';if(a.kind==='stone'||a.kind==='note'){glow(a.x,a.y,38,col+'88');ctx.save();ctx.translate(a.x,a.y);ctx.rotate(Math.PI/4);ctx.fillStyle=col;ctx.fillRect(-7,-7,14,14);ctx.restore()}else character(a.x,a.y,col,'citizen')});s.enemies.forEach(e=>{if(e.isBoss){glow(e.x,e.y,70,'#ff354b88');circle(e.x,e.y,28,'#611b38');ctx.strokeStyle='#ffb4b1';ctx.lineWidth=3;ctx.strokeRect(e.x-25,e.y-42,50,4);ctx.fillStyle='#ff7d8c';ctx.fillRect(e.x-25,e.y-42,50*Math.max(0,e.hp)/30,4)}character(e.x,e.y,'#d76274','hunter')});s.slashes.forEach(a=>{ctx.strokeStyle='#d8ffb2';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(a.x1,a.y1);ctx.lineTo(a.x2,a.y2);ctx.stroke()});s.particles.forEach(p=>{ctx.globalAlpha=clamp(p.life/p.max,0,1);if(p.ring){ctx.strokeStyle=p.color;ctx.lineWidth=4;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.stroke()}else circle(p.x,p.y,p.size,p.color)});ctx.globalAlpha=1;glow(s.player.x,s.player.y,50,mode===3?'#b790ff66':'#d7f87544');character(s.player.x,s.player.y,'#d8f875','vamp',s.player.angle);if(s.messageTime>0){ctx.fillStyle='#f0f4da';ctx.textAlign='center';ctx.font='bold 18px sans-serif';ctx.fillText(s.message,W/2,50);ctx.textAlign='left'}ctx.restore()}
function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;if(state&&!overlay.classList.contains('hidden')){step(dt);draw()}requestAnimationFrame(frame)}requestAnimationFrame(frame);
